"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[5572],{22537:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":"unreleased","badge":true,"noIndex":false,"className":"docs-version-current","isLast":false,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Introduction","href":"/tests-untp/docs/next/introduction/","docId":"introduction/index","unlisted":false},{"type":"category","label":"Reference Implementation","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Overview","href":"/tests-untp/docs/next/reference-implementation/overview","docId":"reference-implementation/overview","unlisted":false},{"type":"link","label":"Quick Start","href":"/tests-untp/docs/next/reference-implementation/quick-start","docId":"reference-implementation/quick-start","unlisted":false},{"type":"link","label":"System Architecture","href":"/tests-untp/docs/next/reference-implementation/system-architecture","docId":"reference-implementation/system-architecture","unlisted":false},{"type":"category","label":"Authentication","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Tenant Modes","href":"/tests-untp/docs/next/reference-implementation/authentication/tenant-modes","docId":"reference-implementation/authentication/tenant-modes","unlisted":false},{"type":"link","label":"IDP Requirements","href":"/tests-untp/docs/next/reference-implementation/authentication/idp-requirements","docId":"reference-implementation/authentication/idp-requirements","unlisted":false}],"href":"/tests-untp/docs/next/reference-implementation/authentication/"},{"type":"category","label":"Services","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Service Architecture","href":"/tests-untp/docs/next/reference-implementation/services/service-architecture","docId":"reference-implementation/services/service-architecture","unlisted":false},{"type":"category","label":"Verifiable Credential Service","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"VCKit Adapter","href":"/tests-untp/docs/next/reference-implementation/services/verifiable-credential-service/vckit-adapter","docId":"reference-implementation/services/verifiable-credential-service/vckit-adapter","unlisted":false}],"href":"/tests-untp/docs/next/reference-implementation/services/verifiable-credential-service/"},{"type":"category","label":"Storage Service","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"UNCEFACT Storage Adapter","href":"/tests-untp/docs/next/reference-implementation/services/storage-service/uncefact-storage-adapter","docId":"reference-implementation/services/storage-service/uncefact-storage-adapter","unlisted":false}],"href":"/tests-untp/docs/next/reference-implementation/services/storage-service/"},{"type":"category","label":"Identity Resolver Service","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Pyx IDR Adapter","href":"/tests-untp/docs/next/reference-implementation/services/identity-resolver-service/pyx-idr-adapter","docId":"reference-implementation/services/identity-resolver-service/pyx-idr-adapter","unlisted":false}],"href":"/tests-untp/docs/next/reference-implementation/services/identity-resolver-service/"},{"type":"link","label":"Adding an Adapter","href":"/tests-untp/docs/next/reference-implementation/services/adding-an-adapter","docId":"reference-implementation/services/adding-an-adapter","unlisted":false}]},{"type":"category","label":"Data Models","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Bridge Architecture","href":"/tests-untp/docs/next/reference-implementation/data-models/bridge-architecture","docId":"reference-implementation/data-models/bridge-architecture","unlisted":false},{"type":"link","label":"Conformity Handling","href":"/tests-untp/docs/next/reference-implementation/data-models/conformity-handling","docId":"reference-implementation/data-models/conformity-handling","unlisted":false},{"type":"link","label":"Conformity Vocabulary Catalogue","href":"/tests-untp/docs/next/reference-implementation/data-models/conformity-vocabulary-catalogue","docId":"reference-implementation/data-models/conformity-vocabulary-catalogue","unlisted":false},{"type":"link","label":"Adding a Bridge","href":"/tests-untp/docs/next/reference-implementation/data-models/adding-a-bridge","docId":"reference-implementation/data-models/adding-a-bridge","unlisted":false}],"href":"/tests-untp/docs/next/reference-implementation/data-models/"},{"type":"link","label":"Master Data","href":"/tests-untp/docs/next/reference-implementation/master-data/","docId":"reference-implementation/master-data/index","unlisted":false},{"type":"category","label":"API","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Services","href":"/tests-untp/docs/next/reference-implementation/api/services","docId":"reference-implementation/api/services","unlisted":false},{"type":"link","label":"DIDs","href":"/tests-untp/docs/next/reference-implementation/api/dids","docId":"reference-implementation/api/dids","unlisted":false},{"type":"link","label":"Data Models","href":"/tests-untp/docs/next/reference-implementation/api/data-models","docId":"reference-implementation/api/data-models","unlisted":false},{"type":"link","label":"Render Templates","href":"/tests-untp/docs/next/reference-implementation/api/render-templates","docId":"reference-implementation/api/render-templates","unlisted":false},{"type":"link","label":"Organisations","href":"/tests-untp/docs/next/reference-implementation/api/organisations","docId":"reference-implementation/api/organisations","unlisted":false},{"type":"link","label":"Facilities","href":"/tests-untp/docs/next/reference-implementation/api/facilities","docId":"reference-implementation/api/facilities","unlisted":false},{"type":"link","label":"Products","href":"/tests-untp/docs/next/reference-implementation/api/products","docId":"reference-implementation/api/products","unlisted":false},{"type":"link","label":"Registrars","href":"/tests-untp/docs/next/reference-implementation/api/registrars","docId":"reference-implementation/api/registrars","unlisted":false},{"type":"link","label":"Identifiers","href":"/tests-untp/docs/next/reference-implementation/api/identifiers","docId":"reference-implementation/api/identifiers","unlisted":false},{"type":"link","label":"Credentials","href":"/tests-untp/docs/next/reference-implementation/api/credentials","docId":"reference-implementation/api/credentials","unlisted":false},{"type":"link","label":"Conformity Vocabulary Catalogue","href":"/tests-untp/docs/next/reference-implementation/api/conformity-vocabulary-catalogue","docId":"reference-implementation/api/conformity-vocabulary-catalogue","unlisted":false}]},{"type":"link","label":"Verify Page","href":"/tests-untp/docs/next/reference-implementation/verify-page","docId":"reference-implementation/verify-page","unlisted":false},{"type":"category","label":"Operations","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Startup","href":"/tests-untp/docs/next/reference-implementation/operations/startup","docId":"reference-implementation/operations/startup","unlisted":false},{"type":"link","label":"Custom Seed","href":"/tests-untp/docs/next/reference-implementation/operations/custom-seed","docId":"reference-implementation/operations/custom-seed","unlisted":false},{"type":"link","label":"Database","href":"/tests-untp/docs/next/reference-implementation/operations/database","docId":"reference-implementation/operations/database","unlisted":false},{"type":"link","label":"Logging","href":"/tests-untp/docs/next/reference-implementation/operations/logging","docId":"reference-implementation/operations/logging","unlisted":false},{"type":"link","label":"API Pagination","href":"/tests-untp/docs/next/reference-implementation/operations/api-pagination","docId":"reference-implementation/operations/api-pagination","unlisted":false},{"type":"link","label":"Key Management and Recovery","href":"/tests-untp/docs/next/reference-implementation/operations/key-management","docId":"reference-implementation/operations/key-management","unlisted":false},{"type":"link","label":"Encryption Audit","href":"/tests-untp/docs/next/reference-implementation/operations/encryption-audit","docId":"reference-implementation/operations/encryption-audit","unlisted":false},{"type":"link","label":"Encryption Key Rotation","href":"/tests-untp/docs/next/reference-implementation/operations/encryption-key-rotation","docId":"reference-implementation/operations/encryption-key-rotation","unlisted":false},{"type":"category","label":"Backfills","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Digest Multibase","href":"/tests-untp/docs/next/reference-implementation/operations/backfills/digest-multibase","docId":"reference-implementation/operations/backfills/digest-multibase","unlisted":false},{"type":"link","label":"Decryption Keys","href":"/tests-untp/docs/next/reference-implementation/operations/backfills/decryption-keys","docId":"reference-implementation/operations/backfills/decryption-keys","unlisted":false},{"type":"link","label":"Credential Details","href":"/tests-untp/docs/next/reference-implementation/operations/backfills/credential-details","docId":"reference-implementation/operations/backfills/credential-details","unlisted":false}],"href":"/tests-untp/docs/next/reference-implementation/operations/backfills/"}]}]},{"type":"link","label":"Test Suites","href":"/tests-untp/docs/next/test-suites/","docId":"test-suites/index","unlisted":false},{"type":"category","label":"Migration Guides","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Reference Implementation v0.4","href":"/tests-untp/docs/next/migration-guides/ri-v0.4","docId":"migration-guides/ri-v0.4","unlisted":false},{"type":"link","label":"UNTP v0.7.0","href":"/tests-untp/docs/next/migration-guides/v0.7.0","docId":"migration-guides/v0.7.0","unlisted":false},{"type":"link","label":"UNTP v0.6.0","href":"/tests-untp/docs/next/migration-guides/v0.6.0","docId":"migration-guides/v0.6.0","unlisted":false}],"href":"/tests-untp/docs/next/migration-guides/"},{"type":"link","label":"Version Mapping","href":"/tests-untp/docs/next/version-mapping/","docId":"version-mapping/index","unlisted":false}]},"docs":{"introduction/index":{"id":"introduction/index","title":"Introduction","description":"The UN Transparency Protocol (UNTP) Test Suite is a comprehensive set of tools for implementing, testing, and demonstrating the UNTP specification. It provides everything needed to issue UNTP-compliant verifiable credentials, validate them against the specification, and verify conformance across technical and semantic dimensions.","sidebar":"tutorialSidebar"},"migration-guides/index":{"id":"migration-guides/index","title":"Migration Guides","description":"","sidebar":"tutorialSidebar"},"migration-guides/ri-v0.4":{"id":"migration-guides/ri-v0.4","title":"Reference Implementation v0.4","description":"Back up the Reference Implementation database, and record the encryption key the","sidebar":"tutorialSidebar"},"migration-guides/v0.6.0":{"id":"migration-guides/v0.6.0","title":"UNTP v0.6.0","description":"Overview","sidebar":"tutorialSidebar"},"migration-guides/v0.7.0":{"id":"migration-guides/v0.7.0","title":"UNTP v0.7.0","description":"Before migrating to version 0.3 of the Reference Implementation, back up the data held in its external systems, in particular the storage service and the identity resolver. Both of these dependent services receive a major upgrade in this release, so review their migration guides first: the storage service v4 migration guide and the Pyx Identity Resolver v4 migration guide.","sidebar":"tutorialSidebar"},"reference-implementation/api/conformity-vocabulary-catalogue":{"id":"reference-implementation/api/conformity-vocabulary-catalogue","title":"Conformity Vocabulary Catalogue","description":"This API lets an issuer browse the conformity schemes registered in this Reference Implementation, drilling from a scheme to the profiles it publishes, and from a profile to the criteria it defines. The URIs these endpoints return are the ones you put in a credential\'s conformity claim.","sidebar":"tutorialSidebar"},"reference-implementation/api/credentials":{"id":"reference-implementation/api/credentials","title":"Credentials","description":"Credentials are the core output of the Reference Implementation. Everything else in the system \u2014 DIDs, services, data models, identifiers, and master data \u2014 exists to support one goal: issuing trusted, verifiable digital documents about products, facilities, organisations, and supply chain events.","sidebar":"tutorialSidebar"},"reference-implementation/api/data-models":{"id":"reference-implementation/api/data-models","title":"Data Models","description":"The data models API manages data models \u2014 the schema definitions that describe the structure and semantics of each UNTP-compliant verifiable credential type. All credentials issued by the Reference Implementation are based on UNTP core data models at a specific version.","sidebar":"tutorialSidebar"},"reference-implementation/api/dids":{"id":"reference-implementation/api/dids","title":"DIDs","description":"The DIDs API manages Decentralised Identifiers (DIDs), the cryptographic identities that the Reference Implementation uses to sign verifiable credentials. Every credential issued by the Reference Implementation is signed with a DID, either one the tenant has provisioned or the system default DID available to all tenants.","sidebar":"tutorialSidebar"},"reference-implementation/api/facilities":{"id":"reference-implementation/api/facilities","title":"Facilities","description":"The Facilities API manages facilities \u2014 the physical locations (factories, warehouses, farms, processing plants) where products are manufactured, stored, or processed. Facilities are one of the core master data entities referenced when issuing UNTP credentials.","sidebar":"tutorialSidebar"},"reference-implementation/api/identifiers":{"id":"reference-implementation/api/identifiers","title":"Identifiers","description":"The Identifiers API manages identifier schemes, identifiers, and links \u2014 the building blocks that connect physical or logical entities (products, facilities, organisations) to their digital credentials via an Identity Resolver (IDR). Identifier schemes define the rules for a class of identifiers (e.g. GTIN, ABN), identifiers are specific values under those schemes, and links are published references from an identifier to credential resources on an upstream IDR service.","sidebar":"tutorialSidebar"},"reference-implementation/api/organisations":{"id":"reference-implementation/api/organisations","title":"Organisations","description":"The Organisations API manages organisations \u2014 the business entities that produce products and operate facilities within the Reference Implementation. Organisations are one of the core master data entities referenced across all UNTP credential types.","sidebar":"tutorialSidebar"},"reference-implementation/api/products":{"id":"reference-implementation/api/products","title":"Products","description":"The Products API manages products \u2014 the goods, materials, and items that move through the supply chain. The Reference Implementation stores product records as tenant-scoped master data that can be referenced by UNTP credentials.","sidebar":"tutorialSidebar"},"reference-implementation/api/registrars":{"id":"reference-implementation/api/registrars","title":"Registrars","description":"The Registrars API manages registrars \u2014 the organisations that maintain identifier schemes (e.g. GS1 for GTIN barcodes, the ATO for Australian Business Numbers). Registrars are one of the foundational configuration entities that underpin identifier schemes and, by extension, the identifiers assigned to products, facilities, and organisations.","sidebar":"tutorialSidebar"},"reference-implementation/api/render-templates":{"id":"reference-implementation/api/render-templates","title":"Render Templates","description":"The render templates API manages render templates \u2014 the HTML templates that control how UNTP verifiable credentials are visually presented. Every credential issued by the Reference Implementation can include a render template that defines how the credential should be displayed to a human viewer.","sidebar":"tutorialSidebar"},"reference-implementation/api/services":{"id":"reference-implementation/api/services","title":"Services","description":"The services API manages service instances \u2014 the configurations that connect the Reference Implementation to its dependent services (verifiable credential services, storage services, and identity resolver services).","sidebar":"tutorialSidebar"},"reference-implementation/authentication/authentication":{"id":"reference-implementation/authentication/authentication","title":"Authentication","description":"The Reference Implementation delegates authentication to a federated identity provider (IDP) and supports two methods of access: browser sessions and service accounts. Both methods use the same IDP to verify identity and resolve the user\'s tenant.","sidebar":"tutorialSidebar"},"reference-implementation/authentication/idp-requirements":{"id":"reference-implementation/authentication/idp-requirements","title":"IDP Requirements","description":"The Reference Implementation delegates authentication to a federated identity provider (IDP). This page describes the token claims, environment variables, and IDP configuration required for each tenant mode.","sidebar":"tutorialSidebar"},"reference-implementation/authentication/tenant-modes":{"id":"reference-implementation/authentication/tenant-modes","title":"Tenant Modes","description":"The Reference Implementation operates in one of two tenant modes \u2014 open or closed \u2014 which determines how tenants are created and how identities are associated with them. The mode is set at the instance level.","sidebar":"tutorialSidebar"},"reference-implementation/data-models/adding-a-bridge":{"id":"reference-implementation/data-models/adding-a-bridge","title":"Adding a Bridge","description":"This guide walks through adding a data model bridge for a new version of a UNTP core data model. The process follows the same delta pattern used by the existing bridges.","sidebar":"tutorialSidebar"},"reference-implementation/data-models/bridge-architecture":{"id":"reference-implementation/data-models/bridge-architecture","title":"Bridge Architecture","description":"The overview describes what data model bridges do \u2014 map between stable entity records and evolving credential structures. This page explains how that mapping is implemented, how versions are managed, and how bridges are resolved at runtime.","sidebar":"tutorialSidebar"},"reference-implementation/data-models/conformity-handling":{"id":"reference-implementation/data-models/conformity-handling","title":"Conformity Handling","description":"Several UNTP credential types carry conformity data \u2014 references to standards, regulations, and assessment criteria that describe what a product, facility, or organisation has been assessed against. This page explains how conformity data flows through the system, how different credential types represent it, and how the Reference Implementation validates conformity content.","sidebar":"tutorialSidebar"},"reference-implementation/data-models/conformity-vocabulary-catalogue":{"id":"reference-implementation/data-models/conformity-vocabulary-catalogue","title":"Conformity Vocabulary Catalogue","description":"A conformity claim in a credential records what was assessed and what the assessment found, but it does not carry the definitions it is assessing against. Instead it points at them: a conformity scheme published by whoever owns it, usually a versioned profile within that scheme, and the criteria the assessment covered. Those pointers are URIs, and a claim may name fewer of them than you expect, since a profile is not required.","sidebar":"tutorialSidebar"},"reference-implementation/data-models/index":{"id":"reference-implementation/data-models/index","title":"Data Model Bridges","description":"The UNTP specification defines several credential types \u2014 Digital Product Passport, Digital Conformity Credential, Digital Facility Record, and others. Each has its own semantic structure that evolves across specification versions. But the Reference Implementation\'s internal entities \u2014 organisations, facilities, products, and conformity vocabulary profiles \u2014 are stable. A tenant\'s organisation record doesn\'t change just because a new UNTP version is released.","sidebar":"tutorialSidebar"},"reference-implementation/master-data/index":{"id":"reference-implementation/master-data/index","title":"Overview","description":"The Reference Implementation stores master data \u2014 the stable records that describe the real-world things credentials are issued about. UNTP credentials reference organisations, facilities, and products \u2014 these are not created fresh for each credential but maintained as persistent, reusable records that predate and outlive any individual credential.","sidebar":"tutorialSidebar"},"reference-implementation/operations/api-pagination":{"id":"reference-implementation/operations/api-pagination","title":"API Pagination","description":"List endpoints return results in pages. A client controls its page with the limit (page size) and offset (records to skip) query parameters.","sidebar":"tutorialSidebar"},"reference-implementation/operations/backfills/credential-details":{"id":"reference-implementation/operations/backfills/credential-details","title":"Credential Details","description":"Reads stored credentials that predate descriptive-field capture and writes the library-facing name, issuer, subject, and validity columns, plus the spec version the matching data-model bridge was resolved with.","sidebar":"tutorialSidebar"},"reference-implementation/operations/backfills/decryption-keys":{"id":"reference-implementation/operations/backfills/decryption-keys","title":"Decryption Keys","description":"Wraps credential decryption keys that are still stored in plaintext into encrypted envelopes under DATAENCRYPTIONKEY.","sidebar":"tutorialSidebar"},"reference-implementation/operations/backfills/digest-multibase":{"id":"reference-implementation/operations/backfills/digest-multibase","title":"Digest Multibase","description":"Converts the stored digest on credentials and render templates from the legacy hexadecimal form to the multibase encoding the application now writes.","sidebar":"tutorialSidebar"},"reference-implementation/operations/backfills/index":{"id":"reference-implementation/operations/backfills/index","title":"Backfills","description":"A migration changes the shape of the tables. It does not always bring the rows that already exist into line with what the new version writes. A backfill does that second part, converting existing rows to the format the current version expects.","sidebar":"tutorialSidebar"},"reference-implementation/operations/custom-seed":{"id":"reference-implementation/operations/custom-seed","title":"Custom Seed","description":"The Reference Implementation seeds a set of default records on startup: data models, render templates, and service instances. Registrars and identifier schemes are not among them. They come from the manifest described here, so an instance has the registrars and schemes its deployer supplies and no others.","sidebar":"tutorialSidebar"},"reference-implementation/operations/database":{"id":"reference-implementation/operations/database","title":"Database","description":"The Reference Implementation uses a PostgreSQL database to store all of its data \u2014 tenants, users, service registrations, credentials metadata, configuration, and more. See System Architecture for what the database contains and how it relates to the external services.","sidebar":"tutorialSidebar"},"reference-implementation/operations/encryption-audit":{"id":"reference-implementation/operations/encryption-audit","title":"Encryption Audit","description":"The Reference Implementation encrypts three kinds of data at rest under DATAENCRYPTIONKEYencryption command answers the question exhaustively: it attempts to decrypt every stored envelope under the active key and reports the result per store, without writing anything.","sidebar":"tutorialSidebar"},"reference-implementation/operations/encryption-key-rotation":{"id":"reference-implementation/operations/encryption-key-rotation","title":"Encryption Key Rotation","description":"The Reference Implementation encrypts service instance configurations, credential decryption keys and idempotent-retry response bodies at rest under DATAENCRYPTIONKEY. Each stored envelope opens only under the key that wrote it, so changing the variable in place makes existing data unreadable. The rotate given the previous key, it re-encrypts every stored envelope under the new active key.","sidebar":"tutorialSidebar"},"reference-implementation/operations/key-management":{"id":"reference-implementation/operations/key-management","title":"Key Management and Recovery","description":"The Reference Implementation encrypts service instance configurations, credential decryption keys and idempotent-retry response bodies at rest under DATAENCRYPTIONKEY. This page is the operational contract for that key: how to generate and hold it, how backups pair with it, and how recovery works. The Encryption Audit and Encryption Key Rotation pages own the two procedures this contract relies on.","sidebar":"tutorialSidebar"},"reference-implementation/operations/logging":{"id":"reference-implementation/operations/logging","title":"Logging","description":"The Reference Implementation produces structured logs for every request and operation. Logs include contextual information \u2014 such as correlation IDs, user IDs, and tenant IDs \u2014 that make it straightforward to trace a request through the system and diagnose issues.","sidebar":"tutorialSidebar"},"reference-implementation/operations/startup":{"id":"reference-implementation/operations/startup","title":"Startup","description":"Before the Reference Implementation begins accepting requests, its database schema must be up to date, and a set of default records must exist for the system to function, such as data models, default service instances, and render templates.","sidebar":"tutorialSidebar"},"reference-implementation/overview":{"id":"reference-implementation/overview","title":"Overview","description":"The Reference Implementation is a ready-to-deploy, multi-tenant application that lets organisations issue, store, publish, and verify UNTP credentials \u2014 without needing to understand the underlying standards or build anything from scratch. This page explains why it exists, who it serves, and how organisations can progressively take ownership of the services it orchestrates.","sidebar":"tutorialSidebar"},"reference-implementation/quick-start":{"id":"reference-implementation/quick-start","title":"Quick Start","description":"This page walks through getting an instance of the Reference Implementation running using Docker Compose. By the end, you will have the Reference Implementation and all of its dependent services running locally.","sidebar":"tutorialSidebar"},"reference-implementation/services/adding-an-adapter":{"id":"reference-implementation/services/adding-an-adapter","title":"Adding an Adapter","description":"The Reference Implementation uses an adapter pattern to communicate with external services. If an organisation wants to integrate a service that is not yet supported, they can contribute a new adapter to the services package.","sidebar":"tutorialSidebar"},"reference-implementation/services/identity-resolver-service/index":{"id":"reference-implementation/services/identity-resolver-service/index","title":"Identity Resolver Service","description":"The identity resolver service used by the Reference Implementation registers links for a given identifier so that related information \u2014 such as credentials \u2014 can be discovered. It is an independent external service \u2014 the Reference Implementation communicates with it at runtime but does not include it. The Reference Implementation cannot publish discoverable credentials without this service.","sidebar":"tutorialSidebar"},"reference-implementation/services/identity-resolver-service/pyx-idr-adapter":{"id":"reference-implementation/services/identity-resolver-service/pyx-idr-adapter","title":"Pyx IDR Adapter","description":"The Pyx Identity Resolver is the default identity resolver service bundled with the Reference Implementation.","sidebar":"tutorialSidebar"},"reference-implementation/services/service-architecture":{"id":"reference-implementation/services/service-architecture","title":"Service Architecture","description":"The Reference Implementation relies on three external services \u2014 a verifiable credential service, a storage service, and an identity resolver service. Rather than being tightly coupled to specific implementations, it uses an adapter pattern that allows each service to be swapped independently. This page explains how that works, how service instances are resolved, and how new adapters can be contributed.","sidebar":"tutorialSidebar"},"reference-implementation/services/storage-service/index":{"id":"reference-implementation/services/storage-service/index","title":"Storage Service","description":"The storage service used by the Reference Implementation stores credentials, render templates, and other binary data. It is an independent external service \u2014 the Reference Implementation communicates with it at runtime but does not include it. It supports both public and private storage modes \u2014 public storage returns a URI and integrity hash, while private storage encrypts the content and additionally returns a decryption key. The Reference Implementation cannot publish credentials without this service.","sidebar":"tutorialSidebar"},"reference-implementation/services/storage-service/uncefact-storage-adapter":{"id":"reference-implementation/services/storage-service/uncefact-storage-adapter","title":"UNCEFACT Storage Adapter","description":"The UNCEFACT Storage Service is the default storage service bundled with the Reference Implementation.","sidebar":"tutorialSidebar"},"reference-implementation/services/verifiable-credential-service/index":{"id":"reference-implementation/services/verifiable-credential-service/index","title":"Verifiable Credential Service","description":"The verifiable credential service used by the Reference Implementation signs and verifies W3C Verifiable Credentials, creates and manages Decentralised Identifiers (DIDs), and handles cryptographic key material. It is an independent external service \u2014 the Reference Implementation communicates with it at runtime but does not include it. The Reference Implementation cannot issue or verify credentials without this service.","sidebar":"tutorialSidebar"},"reference-implementation/services/verifiable-credential-service/vckit-adapter":{"id":"reference-implementation/services/verifiable-credential-service/vckit-adapter","title":"VCKit Adapter","description":"VCKit is an open-source verifiable credential toolkit that provides credential signing, verification, DID management, and cryptographic key management. It is the default verifiable credential service bundled with the Reference Implementation.","sidebar":"tutorialSidebar"},"reference-implementation/system-architecture":{"id":"reference-implementation/system-architecture","title":"System Architecture","description":"The Reference Implementation is a single application \u2014 a set of REST APIs and a web UI (currently under active development). It requires a PostgreSQL database for persistent storage and a federated identity provider (IDP) for authentication. On its own, it does not sign credentials, store files, or resolve identifiers. These capabilities are provided by independent external services \u2014 a verifiable credential service, a storage service, and an identity resolver service \u2014 each running and provisioned separately.","sidebar":"tutorialSidebar"},"reference-implementation/verify-page":{"id":"reference-implementation/verify-page","title":"Verify Page","description":"The verify page (/verify) is a publicly accessible web page for verifying UNTP credentials. It does not require authentication \u2014 anyone with a verification link can use it. This is the primary entry point for credential recipients, specification readers following links to example credentials, and supply chain partners verifying credentials they have received.","sidebar":"tutorialSidebar"},"test-suites/index":{"id":"test-suites/index","title":"Test Suites","description":"The UNTP test suite is being refactored. The refactored suite will be distributed","sidebar":"tutorialSidebar"},"version-mapping/index":{"id":"version-mapping/index","title":"Version Mapping","description":"","sidebar":"tutorialSidebar"}}}}')}}]);